pending=[]
for name,item in edits.items():
 p=root/name;raw=p.read_bytes();sha=hashlib.sha256(raw).hexdigest()
 if sha==item['after']:continue
 assert sha==item['before'], 'Base changed, review instead of overwrite: '+name
 text=raw.decode()
 for a,b,replacement in reversed(item['changes']):text=text[:a]+replacement+text[b:]
 out=text.encode();assert hashlib.sha256(out).hexdigest()==item['after'],name
 pending.append((p,out))
for p,data in pending:p.write_bytes(data)
print('Applied',len(pending),'checked public graphics source changes.')
